43	pub fn load_changesets(
44	    root: &Path,
45	    cfg: &ResolvedConfig,
46	) -> Result<Vec<LoadedChangeset>, GraphError> {
47	    let dir = root.join(&cfg.changesets_dir);
48	    if !dir.exists() {
49	        return Ok(Vec::new());
50	    }
51	
52	    let entries = fs::read_dir(&dir).map_err(|e| callisto_model::ManifestError::Read {
53	        path: dir.clone(),
54	        message: e.to_string(),
55	    })?;
56	
57	    let mut files = Vec::new();
58	    for entry in entries.flatten() {
59	        let path = entry.path();
60	        if path.is_file() && path.extension().and_then(|s| s.to_str()) == Some("md") {
61	            if let Some(file_name) = path.file_name().and_then(|s| s.to_str()) {
62	                if file_name != "README.md" && file_name != "config.json" && file_name != "pre.json"
63	                {
64	                    files.push(path);
65	                }
66	            }
67	        }
68	    }
69	
70	    files.sort();
71	
72	    let mut loaded = Vec::new();
73	    for path in files {
74	        let content =
75	            fs::read_to_string(&path).map_err(|e| callisto_model::ManifestError::Read {
76	                path: path.clone(),
77	                message: e.to_string(),
78	            })?;
79	        let changeset = parse_changeset(&content).map_err(|e| GraphError::ParseChangeset {
80	            path: path.clone(),
81	            source: e,
82	        })?;
83	        let stem = path
84	            .file_stem()
85	            .and_then(|s| s.to_str())
86	            .unwrap_or("")
87	            .to_string();
88	        let rel_path = path.strip_prefix(root).unwrap_or(&path).to_path_buf();
89	        loaded.push(LoadedChangeset {
90	            path: rel_path,
91	            id: stem,
92	            changeset,
93	        });
94	    }
