  1 │ //! Regression test for eager `TagIndex` construction.
  2 │ //!
  3 │ //! `Workspace::load` used to build the full `TagIndex` unconditionally --
  4 │ //! even for callers (e.g. `callisto add`'s non-interactive path, `callisto
  5 │ //! init`, `callisto add`'s interactive package-selection step) that never
  6 │ //! consult tags at all. `TagIndex::build` fetches the repo's full tag list
  7 │ //! via `callisto_vcs::GitRepository` (gix) or, when gix is unavailable --
  8 │ //! permanently the case on `wasm32`, where each `CommandRunner` round-trip
  9 │ //! is a full Extism guest<->host context switch -- via a `CommandRunner`-
 10 │ //! shelled `git tag --list` call. Neither should ever happen just because a
 11 │ //! `Workspace` was loaded; it should happen at most once, and only once
 12 │ //! something actually calls `Workspace::tags()`.
 13 │ //!
 14 │ //! This test forces the `CommandRunner` fallback deterministically (by
 15 │ //! using a workspace root gix cannot discover as a repo, mirroring the
 16 │ //! `non_repo_dir` fixture in `callisto-graph/src/tags.rs`'s own unit tests)
 17 │ //! and counts `git tag --list` invocations to prove laziness.
 18 │ 
 19 │ use std::path::Path;
 20 │ use std::sync::atomic::{AtomicUsize, Ordering};
 21 │ 
 22 │ use callisto_graph::locate::IgnoreWalkLocator;
 23 │ use callisto_graph::Workspace;
 24 │ use callisto_model::{CommandError, CommandOutput, CommandRunner};
 25 │ 
 26 │ /// A `CommandRunner` double that counts every `git tag --list` invocation
 27 │ /// it receives; answers with an empty tag list so `TagIndex::build` (if
 28 │ /// invoked) succeeds trivially.
 29 │ struct CountingTagListRunner {
 30 │     tag_list_calls: AtomicUsize,
 31 │ }
 32 │ 
 33 │ impl CommandRunner for CountingTagListRunner {
 34 │     fn run(
 35 │         &self,
 36 │         program: &str,
 37 │         args: &[&str],
 38 │         _cwd: &Path,
 39 │     ) -> Result<CommandOutput, CommandError> {
 40 │         assert_eq!(
 41 │             program, "git",
 42 │             "only `git` should ever be shelled out to here"
 43 │         );
 44 │         if args == ["tag", "--list"] {
 45 │             self.tag_list_calls.fetch_add(1, Ordering::SeqCst);
 46 │         }
 47 │         Ok(CommandOutput {
 48 │             exit_code: Some(0),
 49 │             stdout: String::new(),
 50 │             stderr: String::new(),
 51 │         })
 52 │     }
 53 │ }
 54 │ 
 55 │ fn write_minimal_workspace(root: &Path) {
 56 │     std::fs::write(
 57 │         root.join("Cargo.toml"),
 58 │         "[workspace]\nmembers = [\"crates/*\"]\nresolver = \"2\"\n",
 59 │     )
 60 │     .unwrap();
 61 │     let pkg_dir = root.join("crates/my-app");
 62 │     std::fs::create_dir_all(&pkg_dir).unwrap();
 63 │     std::fs::write(
 64 │         pkg_dir.join("Cargo.toml"),
 65 │         "[package]\nname = \"my-app\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
 66 │     )
 67 │     .unwrap();
 68 │ }
 69 │ 
 70 │ #[test]
 71 │ fn workspace_load_does_not_build_tag_index_until_tags_is_called() {
 72 │     let tmp = tempfile::tempdir().unwrap();
 73 │     let root = tmp.path();
 74 │     write_minimal_workspace(root);
 75 │ 
 76 │     // Deliberately no `git init`: guarantees `GitRepository::discover` fails
 77 │     // (the same situation `wasm32` is permanently in), so *if* `TagIndex`
 78 │     // construction ran, it would deterministically fall through to the
 79 │     // `CommandRunner` `git tag --list` call this test counts.
 80 │     assert!(
 81 │         callisto_vcs::GitRepository::discover(root).is_err(),
 82 │         "test fixture must not be discoverable as a Git repo"
 83 │     );
 84 │ 
 85 │     let locator = IgnoreWalkLocator::new(root);
 86 │     let runner = CountingTagListRunner {
 87 │         tag_list_calls: AtomicUsize::new(0),
 88 │     };
 89 │ 
 90 │     let ws = Workspace::load(root.to_path_buf(), &locator, &runner)
 91 │         .expect("Workspace::load should succeed");
 92 │ 
 93 │     assert_eq!(
 94 │         runner.tag_list_calls.load(Ordering::SeqCst),
 95 │         0,
 96 │         "Workspace::load must not build the tag index eagerly -- it should be \
 97 │          deferred until something actually calls Workspace::tags()"
 98 │     );
 99 │ 
100 │     let _tags = ws.tags().expect("tags() should build the index lazily");
101 │     assert_eq!(
102 │         runner.tag_list_calls.load(Ordering::SeqCst),
103 │         1,
104 │         "the first Workspace::tags() call should build the tag index exactly once"
105 │     );
106 │ 
107 │     let _tags_again = ws
108 │         .tags()
109 │         .expect("second call should reuse the cached index");
110 │     assert_eq!(
111 │         runner.tag_list_calls.load(Ordering::SeqCst),
112 │         1,
113 │         "a second Workspace::tags() call must not rebuild the tag index"
114 │     );
115 │ }

