12	pub struct PublishOptions {
13	    /// When non-empty, only packages whose bare name (without ecosystem prefix)
14	    /// appears in this list are included in the plan. An empty `only` list
15	    /// means "include all packages" (the default).
16	    pub only: Vec<String>,
17	}
