19	/// Validates a `publishConfig.registry` URL read from a package's own
20	/// `package.json` before it is threaded into the publish plan (and
21	/// eventually into `npm publish --registry <url>` / `npm view --registry
22	/// <url>`, both run with `NPM_TOKEN` live in the process environment in CI).
23	///
24	/// `publishConfig.registry` is manifest-controlled data -- something a PR
25	/// author can set in their own package.json -- not operator-controlled
26	/// config, so it must never be trusted verbatim as a publish destination.
27	/// Two checks are enforced, mirroring the leading-`-` flag-injection guard
28	/// already applied to package names before they reach these same CLI
29	/// invocations (see `SubprocessRegistryClient::npm_publish`):
30	///
31	/// 1. The URL must use the `https` scheme. A scheme downgrade (e.g. `http`)
32	///    is rejected even if the host would otherwise be approved, since scheme
33	///    downgrade is itself part of the attack this guard defends against.
34	/// 2. The URL must exactly match a `url` configured on an `npm`-kind entry
35	///    in the operator's `[registries]` table in `callisto.toml`.
36	///
37	/// If the operator has configured no custom npm registries at all (no
38	/// `[registries.*]` block with `kind = "npm"` and a `url`), any override is
39	/// rejected. This is the conservative choice: `callisto.toml`, not an
40	/// attacker-influenced `package.json`, must always be the source of truth
41	/// for where credentials-bearing publish requests are allowed to go, so
42	/// operators who need a private npm registry must opt in explicitly by
43	/// declaring it in `[registries]`.
44	fn validate_npm_registry_url(
45	    url: &str,
46	    package: &PackageId,
47	    registries: &std::collections::BTreeMap<RegistryKey, crate::config::RegistryConfig>,
48	) -> Result<(), GraphError> {
49	    let is_approved = url.starts_with("https://")
50	        && registries
51	            .values()
52	            .any(|cfg| cfg.kind == Ecosystem::Npm && cfg.url.as_deref() == Some(url));
53	
54	    if is_approved {
55	        Ok(())
56	    } else {
57	        Err(GraphError::UntrustedNpmRegistry {
58	            package: package.clone(),
59	            url: url.to_string(),
60	        })
61	    }
62	}
