64	pub fn plan_publish<R: CommandRunner, D: DependencyResolver>(
65	    ws: &Workspace<'_, R, D>,
66	    opts: &PublishOptions,
67	) -> Result<PublishPlan, GraphError> {
68	    let mut rust_crates = Vec::new();
69	    let mut npm_main_packages = Vec::new();
70	    let mut npm_platform_packages = Vec::new();
71	    let mut pypi_packages = Vec::new();
72	    let mut releases = Vec::new();
73	
74	    let base_versions = ws.base_versions()?;
75	    let inference = crate::infer::NoInference;
76	    let mut diagnostics: Vec<callisto_model::Diagnostic> = Vec::new();
77	    let version_plan = match crate::commands::version::plan_version(
78	        ws,
79	        &inference,
80	        &crate::commands::version::VersionOptions::default(),
81	    ) {
