41	pub fn load_changesets(
42	    root: &Path,
43	    cfg: &ResolvedConfig,
44	) -> Result<Vec<LoadedChangeset>, GraphError> {
45	    let dir = root.join(&cfg.changesets_dir);
46	    if !dir.exists() {
47	        return Ok(Vec::new());
48	    }
49	
50	    let entries = fs::read_dir(&dir).map_err(|e| callisto_model::ManifestError::Read {
51	        path: dir.clone(),
52	        message: e.to_string(),
53	    })?;
54	
55	    let mut files = Vec::new();
56	    for entry in entries.flatten() {
57	        let path = entry.path();
58	        if path.is_file() && path.extension().and_then(|s| s.to_str()) == Some("md") {
59	            if let Some(file_name) = path.file_name().and_then(|s| s.to_str()) {
60	                if file_name != "README.md" && file_name != "config.json" && file_name != "pre.json"
61	                {
62	                    files.push(path);
63	                }
64	            }
65	        }
66	    }
67	
68	    files.sort();
69	
70	    let mut loaded = Vec::new();
71	    for path in files {
72	        let content =
73	            fs::read_to_string(&path).map_err(|e| callisto_model::ManifestError::Read {
74	                path: path.clone(),
75	                message: e.to_string(),
76	            })?;
77	        let changeset = parse_changeset(&content).map_err(|e| GraphError::ParseChangeset {
78	            path: path.clone(),
79	            source: e,
80	        })?;
81	        let stem = path
82	            .file_stem()
83	            .and_then(|s| s.to_str())
84	            .unwrap_or("")
85	            .to_string();
86	        let rel_path = path.strip_prefix(root).unwrap_or(&path).to_path_buf();
87	        loaded.push(LoadedChangeset {
88	            path: rel_path,
89	            id: stem,
90	            changeset,
91	        });
92	    }
