 49 /// Result of reading the `napi.targets` field from a package.json. Distinct
 50 /// from `Option<Vec<String>>` so AC-001b (present-but-empty vs absent) is a
 51 /// type-level distinction, not a magic-empty-vec convention.
 52 #[derive(Clone, Debug, PartialEq, Eq)]
 53 pub(crate) enum NapiTargetsField {
 54     Absent,
 55     Present(Vec<String>),
 56 }
 57 
 58 /// Reads `napi.targets` directly from `pkg_json_path`. A missing `napi` key
 59 /// or missing `napi.targets` key is `Absent` (AC-003: no platformTargets
 60 /// entry). A present `napi.targets` that is not a JSON array of strings is a
 61 /// hard error (AC-010c) -- unlike `NapiTargetsIndex::load`, which silently
 62 /// drops non-array values.
 63 pub(crate) fn read_napi_targets(pkg_json_path: &Path) -> Result<NapiTargetsField, GraphError> {
 64     let content = std::fs::read_to_string(pkg_json_path).map_err(|e| {
 65         GraphError::Manifest(ManifestError::Read {
 66             path: pkg_json_path.to_path_buf(),
 67             message: e.to_string(),
 68         })
 69     })?;
 70     let val: serde_json::Value = serde_json::from_str(&content).map_err(|e| {
 71         GraphError::Manifest(ManifestError::Parse {
 72             path: pkg_json_path.to_path_buf(),
 73             format: ManifestFormat::PackageJson,
 74             message: e.to_string(),
 75         })
 76     })?;
 77 
 78     let Some(napi) = val.get("napi") else {
 79         return Ok(NapiTargetsField::Absent);
 80     };
 81     let Some(targets) = napi.get("targets") else {
 82         return Ok(NapiTargetsField::Absent);
 83     };
 84 
 85     let arr = targets.as_array().ok_or_else(|| {
 86         GraphError::Manifest(ManifestError::Parse {
 87             path: pkg_json_path.to_path_buf(),
 88             format: ManifestFormat::PackageJson,
 89             message: "napi.targets must be a JSON array of strings".to_string(),
 90         })
 91     })?;
 92 
 93     let mut out = Vec::with_capacity(arr.len());
 94     for item in arr {
 95         let s = item.as_str().ok_or_else(|| {
 96             GraphError::Manifest(ManifestError::Parse {
 97                 path: pkg_json_path.to_path_buf(),
 98                 format: ManifestFormat::PackageJson,
 99                 message: "napi.targets entries must all be strings".to_string(),
100             })

