pub(crate) fn assemble_platform_target_group(
    package_dir_abs: &Path,
    package_dir_rel: &str,
    package_name: &str,
    package_id: &PackageId,
) -> Result<(Option<PlatformTargetGroup>, Vec<Diagnostic>), GraphError> {
