49	/// Result of reading the `napi.targets` field from a package.json. Distinct
50	/// from `Option<Vec<String>>` so AC-001b (present-but-empty vs absent) is a
51	/// type-level distinction, not a magic-empty-vec convention.
52	#[derive(Clone, Debug, PartialEq, Eq)]
53	pub(crate) enum NapiTargetsField {
54	    Absent,
55	    Present(Vec<String>),
56	}
57	
58	/// Reads and parses `pkg_json_path` as JSON, if it exists. `Ok(None)` when
59	/// the file is absent -- not every package has a `package.json`.
60	///
61	/// Callers needing more than one field out of the same `package.json` (e.g.
62	/// both `napi.targets` and `engines.node`, see `build_matrix_report`) must
63	/// call this once and pass the resulting `Value` to each field-extraction
64	/// function (`read_napi_targets`, `read_engines_node`) rather than letting
65	/// each one independently re-read and re-parse the file from disk.
66	pub(crate) fn parse_package_json(
67	    pkg_json_path: &Path,
68	) -> Result<Option<serde_json::Value>, GraphError> {
69	    if !pkg_json_path.exists() {
70	        return Ok(None);
71	    }
72	    let content = std::fs::read_to_string(pkg_json_path).map_err(|e| {
73	        GraphError::Manifest(ManifestError::Read {
74	            path: pkg_json_path.to_path_buf(),
75	            message: e.to_string(),
76	        })
77	    })?;
78	    let val: serde_json::Value = serde_json::from_str(&content).map_err(|e| {
79	        GraphError::Manifest(ManifestError::Parse {
80	            path: pkg_json_path.to_path_buf(),
81	            format: ManifestFormat::PackageJson,
82	            message: e.to_string(),
83	        })
84	    })?;
85	    Ok(Some(val))
86	}
87	
88	/// Extracts `napi.targets` from an already-parsed `package.json` value (see
89	/// `parse_package_json`). A missing `napi` key or missing `napi.targets` key
90	/// is `Absent` (AC-003: no platformTargets entry). A present `napi.targets`
91	/// that is not a JSON array of strings is a hard error (AC-010c) -- unlike
92	/// `NapiTargetsIndex::load`, which silently drops non-array values.
93	pub(crate) fn read_napi_targets(
94	    pkg_json_path: &Path,
95	    val: &serde_json::Value,
96	) -> Result<NapiTargetsField, GraphError> {
97	    let Some(napi) = val.get("napi") else {
98	        return Ok(NapiTargetsField::Absent);
99	    };
100	    let Some(targets) = napi.get("targets") else {
101	        return Ok(NapiTargetsField::Absent);
102	    };
103	
104	    let arr = targets.as_array().ok_or_else(|| {
105	        GraphError::Manifest(ManifestError::Parse {
106	            path: pkg_json_path.to_path_buf(),
107	            format: ManifestFormat::PackageJson,
108	            message: "napi.targets must be a JSON array of strings".to_string(),
109	        })
110	    })?;
111	
112	    let mut out = Vec::with_capacity(arr.len());
113	    for item in arr {
114	        let s = item.as_str().ok_or_else(|| {
115	            GraphError::Manifest(ManifestError::Parse {
116	                path: pkg_json_path.to_path_buf(),
117	                format: ManifestFormat::PackageJson,
118	                message: "napi.targets entries must all be strings".to_string(),
119	            })
120	        })?;
121	        out.push(s.to_string());
122	    }
123	    Ok(NapiTargetsField::Present(out))
124	}
