126	/// Builds a PlatformTarget for `triple`, combining `triple_to_role`'s
127	/// platform/arch/abi with this module's hostRunner/useCross/artifactName
128	/// table. Returns `None` when `triple` is not recognised by either --
129	/// callers must route that case to an UnrecognisedPlatformTriple diagnostic
130	/// (AC-011) rather than treating it as an error.
131	pub(crate) fn build_platform_target(
132	    triple: &str,
133	    package_dir: &str,
134	    package_name: &str,
135	) -> Option<PlatformTarget> {
136	    let ManifestRole::Platform {
