23	/// Creates one git tag per release in `plan`.
24	///
25	/// `permit` is the dry-run gate: `None` reports the tags that *would* be
26	/// created without touching a single ref, `Some` creates them. It replaces the
27	/// former `TagOptions::dry_run` bool so that the preview branch and the write
28	/// branch cannot disagree -- the write calls simply do not typecheck without a
29	/// permit in hand.
30	pub fn create_tags_with_options<R: CommandRunner, D: DependencyResolver>(
31	    ws: &Workspace<'_, R, D>,
32	    plan: &PublishPlan,
33	    opts: &TagOptions,
34	    permit: Option<&ApplyPermit>,
35	) -> Result<TagReport, GraphError> {
36	    let mut tags = Vec::new();
37	
38	    // `Workspace::git_access` never hard-fails on a missing gix discovery:
39	    // `wasm32` has no gix at all (excluded from that target's dependency
40	    // set), and even natively a failed discovery just means every op below
41	    // runs through the `CommandRunner` fallback instead. Its write
42	    // operations (`create_tag`/`create_floating_major`) additionally
43	    // guarantee a discovered repo's result is authoritative and never
44	    // masked by a shell retry -- see `GitAccess`'s doc comment. Sharing the
45	    // workspace-scoped instance (rather than a fresh `GitAccess::discover`)
46	    // means this command doesn't pay for a second discovery when `ws.tags()`
47	    // below also needs one.
48	    let git = ws.git_access();
49	
50	    for release in &plan.releases {
51	        let tag_str = release.tag_name.as_str();
52	
53	        let Some(permit) = permit else {
54	            if opts.floating_major {
55	                let tmpl = ws.tags()?.template(&release.package);
56	                if let Some(v_str) = tmpl.extract_version_str(release.tag_name.as_str()) {
57	                    let grammar = ws
58	                        .graph
59	                        .packages()
60	                        .find(|p| p.id == release.package)
61	                        .and_then(|p| p.version_grammar().ok())
62	                        .unwrap_or(callisto_model::VersionGrammar::SemVer);
63	                    if let Ok(ver) = callisto_model::Version::parse(v_str, grammar) {
64	                        if let Some(major_tag) = tmpl.render_floating_major(&ver) {
65	                            tags.push(CreatedTag {
66	                                package: release.package.clone(),
67	                                tag_name: major_tag,
68	                                sha: release.sha.clone(),
69	                            });
70	                        }
71	                    }
72	                }
73	            }
74	            tags.push(CreatedTag {
75	                package: release.package.clone(),
76	                tag_name: release.tag_name.clone(),
77	                sha: release.sha.clone(),
78	            });
79	            continue;
80	        };
81	
82	        let already_existed = !ws.git_access().list_tags(Some(tag_str))?.is_empty();
83	
84	        if !already_existed {
85	            let msg = format!("Release {}", tag_str);
86	            git.create_tag(tag_str, &release.sha, Some(&msg), permit)?;
87	        }
88	
89	        if opts.floating_major {
90	            let tmpl = ws.tags()?.template(&release.package);
91	            let ver_str = tmpl.extract_version_str(release.tag_name.as_str());
92	            let grammar = ws
93	                .graph
94	                .packages()
95	                .find(|p| p.id == release.package)
96	                .and_then(|p| p.version_grammar().ok())
97	                .unwrap_or(callisto_model::VersionGrammar::SemVer);
98	
99	            if let Some(v_str) = ver_str {
100	                if let Ok(ver) = callisto_model::Version::parse(v_str, grammar) {
101	                    if let Some(major_tag) = tmpl.render_floating_major(&ver) {
102	                        git.create_floating_major(major_tag.as_str(), &release.sha, permit)?;
103	                        tags.push(CreatedTag {
104	                            package: release.package.clone(),
105	                            tag_name: major_tag,
106	                            sha: release.sha.clone(),
107	                        });
108	                    }
109	                }
110	            }
111	        }
112	
113	        tags.push(CreatedTag {
114	            package: release.package.clone(),
115	            tag_name: release.tag_name.clone(),
116	            sha: release.sha.clone(),
117	        });
118	    }
119	
120	    Ok(TagReport {
121	        schema_version: SCHEMA_VERSION,
122	        created_tags: tags,
123	        diagnostics: Vec::new(),
124	    })
125	}

