<title>Callisto Atlas</title>
<style>
  :root {
    --bg: #EDEAE2;
    --surface: #F7F5EF;
    --surface-2: #E3DFD3;
    --line: #CFC9B8;
    --ink: #211D16;
    --ink-muted: #5B5646;
    --ink-faint: #8B8570;
    --rust: #A8541F;
    --rust-soft: #EFDCC7;
    --ice: #35707E;
    --ice-soft: #DCE9E9;
    --good: #3F6E3F;
    --good-soft: #DEE8D9;
    --amber: #92650F;
    --amber-soft: #F1E3C4;
    --shadow: 0 1px 2px rgba(33,29,22,0.06), 0 8px 24px rgba(33,29,22,0.06);
    --serif: "Iowan Old Style", "Palatino Linotype", "Georgia", serif;
    --display: Georgia, "Times New Roman", serif;
    --mono: ui-monospace, "SF Mono", "Cascadia Code", "JetBrains Mono", Consolas, monospace;
  }

  :root[data-theme="dark"] {
    --bg: #17140F;
    --surface: #1E1A13;
    --surface-2: #262017;
    --line: #3A3224;
    --ink: #EDE7D8;
    --ink-muted: #B2A98F;
    --ink-faint: #766E58;
    --rust: #D97D42;
    --rust-soft: #3A2716;
    --ice: #7FBFCC;
    --ice-soft: #1B3336;
    --good: #8FBF8F;
    --good-soft: #223423;
    --amber: #D7AC53;
    --amber-soft: #362A11;
    --shadow: 0 1px 2px rgba(0,0,0,0.4), 0 8px 28px rgba(0,0,0,0.4);
  }

  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --bg: #17140F;
      --surface: #1E1A13;
      --surface-2: #262017;
      --line: #3A3224;
      --ink: #EDE7D8;
      --ink-muted: #B2A98F;
      --ink-faint: #766E58;
      --rust: #D97D42;
      --rust-soft: #3A2716;
      --ice: #7FBFCC;
      --ice-soft: #1B3336;
      --good: #8FBF8F;
      --good-soft: #223423;
      --amber: #D7AC53;
      --amber-soft: #362A11;
      --shadow: 0 1px 2px rgba(0,0,0,0.4), 0 8px 28px rgba(0,0,0,0.4);
    }
  }

  * { box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    margin: 0;
    background: var(--bg);
    color: var(--ink);
    font-family: var(--serif);
    font-size: 17px;
    line-height: 1.62;
    -webkit-font-smoothing: antialiased;
  }
  ::selection { background: var(--rust-soft); }
  @media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }

  a { color: var(--ice); text-underline-offset: 3px; text-decoration-thickness: 1px; }
  a:focus-visible, button:focus-visible { outline: 2px solid var(--rust); outline-offset: 2px; }

  code, .mono { font-family: var(--mono); }

  .plate-num {
    font-family: var(--mono);
    font-size: 12px;
    letter-spacing: 0.14em;
    color: var(--rust);
    text-transform: uppercase;
  }

  /* ---------- layout shell ---------- */
  .shell {
    max-width: 1220px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 232px minmax(0,1fr);
    gap: 56px;
    padding: 0 28px;
  }
  @media (max-width: 980px) {
    .shell { grid-template-columns: 1fr; }
    .index-wrap { display: none; }
  }

  /* ---------- hero ---------- */
  header.hero {
    border-bottom: 1px solid var(--line);
    padding: 72px 28px 56px;
  }
  .hero-inner { max-width: 1220px; margin: 0 auto; }
  .hero-eyebrow {
    font-family: var(--mono);
    font-size: 12.5px;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--ink-faint);
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 20px;
  }
  .hero-eyebrow .crater {
    width: 9px; height: 9px; border-radius: 50%;
    background: var(--rust);
    box-shadow: 0 0 0 4px var(--rust-soft);
    flex: none;
  }
  h1.title {
    font-family: var(--display);
    font-weight: 700;
    font-size: clamp(3rem, 8vw, 5.4rem);
    letter-spacing: -0.01em;
    margin: 0 0 6px;
    text-wrap: balance;
    line-height: 0.98;
  }
  .title-sub {
    font-family: var(--mono);
    font-size: 13px;
    letter-spacing: 0.1em;
    color: var(--ink-faint);
    text-transform: uppercase;
    margin: 0 0 26px;
  }
  .tagline {
    font-size: 22px;
    color: var(--ink-muted);
    max-width: 60ch;
    margin: 0 0 40px;
    font-style: italic;
  }

  .stat-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    border: 1px solid var(--line);
    border-radius: 4px;
    overflow: hidden;
  }
  .stat-strip .s {
    padding: 18px 20px;
    border-right: 1px solid var(--line);
    background: var(--surface);
  }
  .stat-strip .s:last-child { border-right: none; }
  .stat-strip .n {
    font-family: var(--mono);
    font-size: 26px;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
    color: var(--ink);
  }
  .stat-strip .l {
    font-family: var(--mono);
    font-size: 10.5px;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: var(--ink-faint);
    margin-top: 4px;
  }
  @media (max-width: 640px) {
    .stat-strip { grid-template-columns: 1fr 1fr; }
    .stat-strip .s:nth-child(2) { border-right: none; }
  }

  /* ---------- index rail ---------- */
  .index-wrap { padding-top: 64px; }
  nav.index { position: sticky; top: 28px; }
  nav.index .idx-title {
    font-family: var(--mono);
    font-size: 11px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--ink-faint);
    margin-bottom: 14px;
  }
  nav.index ol {
    list-style: none;
    margin: 0; padding: 0;
    counter-reset: plate;
  }
  nav.index li { counter-increment: plate; }
  nav.index li a {
    display: flex;
    gap: 10px;
    padding: 7px 0;
    color: var(--ink-muted);
    text-decoration: none;
    font-size: 13.5px;
    border-left: 2px solid transparent;
    padding-left: 10px;
    margin-left: -12px;
  }
  nav.index li a::before {
    content: counter(plate, decimal-leading-zero);
    font-family: var(--mono);
    font-size: 11px;
    color: var(--rust);
    flex: none;
    padding-top: 1px;
  }
  nav.index li a:hover { color: var(--ink); border-left-color: var(--rust); }

  /* ---------- main / plates ---------- */
  main { padding: 64px 0 100px; min-width: 0; }
  section.plate { margin-bottom: 84px; scroll-margin-top: 24px; }
  section.plate:last-child { margin-bottom: 0; }

  .plate-head { margin-bottom: 26px; padding-bottom: 14px; border-bottom: 1px solid var(--line); }
  h2.plate-title {
    font-family: var(--display);
    font-size: 2rem;
    font-weight: 700;
    margin: 6px 0 0;
    text-wrap: balance;
  }

  p { margin: 0 0 16px; }
  .lede { font-size: 19px; color: var(--ink); max-width: 68ch; }
  .prose { max-width: 70ch; color: var(--ink-muted); }
  .prose strong { color: var(--ink); font-weight: 650; }
  .prose p:last-child { margin-bottom: 0; }

  blockquote.spec {
    margin: 22px 0;
    padding: 18px 22px;
    border-left: 3px solid var(--rust);
    background: var(--surface);
    border-radius: 0 6px 6px 0;
    font-style: italic;
    color: var(--ink-muted);
    max-width: 66ch;
  }
  blockquote.spec cite {
    display: block;
    margin-top: 10px;
    font-family: var(--mono);
    font-style: normal;
    font-size: 12px;
    letter-spacing: 0.03em;
    color: var(--ink-faint);
  }

  /* ---------- feature specimen cards ---------- */
  .specimen-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
    margin-top: 28px;
  }
  @media (max-width: 720px) { .specimen-grid { grid-template-columns: 1fr; } }
  .specimen {
    background: var(--surface);
    border: 1px solid var(--line);
    border-radius: 6px;
    padding: 22px 24px;
    box-shadow: var(--shadow);
  }
  .specimen .sp-head {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 10px;
    margin-bottom: 10px;
  }
  .specimen .sp-name {
    font-weight: 700;
    font-size: 17px;
    color: var(--ink);
  }
  .specimen .sp-tag {
    font-family: var(--mono);
    font-size: 10px;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--rust);
    white-space: nowrap;
  }
  .specimen .sp-body {
    font-size: 15px;
    color: var(--ink-muted);
  }
  .specimen .sp-body code {
    font-size: 0.88em;
    background: var(--surface-2);
    border: 1px solid var(--line);
    border-radius: 3px;
    padding: 0.05em 0.4em;
    color: var(--ink);
  }

  /* ---------- diagrams ---------- */
  .diagram-frame {
    border: 1px solid var(--line);
    border-radius: 6px;
    background: var(--surface);
    padding: 26px 20px 18px;
    margin: 24px 0;
    box-shadow: var(--shadow);
    overflow-x: auto;
  }
  .diagram-frame .fig-label {
    font-family: var(--mono);
    font-size: 11px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--ink-faint);
    margin-bottom: 14px;
  }
  .diagram-frame pre.mermaid { margin: 0; display: flex; justify-content: center; }

  /* ---------- comparison / positioning ---------- */
  .quote-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
    margin-top: 22px;
  }
  @media (max-width: 720px) { .quote-grid { grid-template-columns: 1fr; } }
  .diffcard {
    border: 1px solid var(--line);
    border-radius: 6px;
    padding: 16px 18px;
    background: var(--surface);
  }
  .diffcard .vs {
    font-family: var(--mono);
    font-size: 11px;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--ink-faint);
    margin-bottom: 6px;
  }
  .diffcard .vs b { color: var(--ink); }
  .diffcard p { font-size: 14.5px; color: var(--ink-muted); margin: 0; }

  .highlight-strip {
    margin-top: 22px;
    padding: 18px 22px;
    border-radius: 6px;
    background: var(--ice-soft);
    border: 1px solid var(--ice);
    color: var(--ink);
    font-size: 15.5px;
  }
  .highlight-strip strong { color: var(--ice); }

  /* ---------- CLI table ---------- */
  .cli-table-wrap { overflow-x: auto; margin-top: 22px; }
  table.cli {
    width: 100%;
    border-collapse: collapse;
    font-size: 14.5px;
    min-width: 560px;
  }
  table.cli th {
    text-align: left;
    font-family: var(--mono);
    font-size: 10.5px;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--ink-faint);
    padding: 0 14px 10px 0;
    border-bottom: 1px solid var(--line);
  }
  table.cli td {
    padding: 11px 14px 11px 0;
    border-bottom: 1px solid var(--line);
    vertical-align: top;
    color: var(--ink-muted);
  }
  table.cli td:first-child, table.cli th:first-child { padding-left: 4px; }
  table.cli code {
    font-family: var(--mono);
    font-size: 13.5px;
    color: var(--ink);
    white-space: nowrap;
  }
  table.cli td.num {
    font-family: var(--mono);
    color: var(--ink);
    font-variant-numeric: tabular-nums;
