198	    pub fn discover(path: impl AsRef<Path>) -> Result<Self, VcsError> {
199	        let p = path.as_ref();
200	        let clean_path = dunce::canonicalize(p).unwrap_or_else(|_| p.to_path_buf());
201	        let repo = gix::discover(&clean_path).map_err(|e| VcsError::RepoNotFound {
202	            path: clean_path,
203	            message: e.to_string(),
204	        })?;
205	        Ok(Self { repo })
206	    }
