208	    #[cfg(target_arch = "wasm32")]
209	    pub fn discover(path: impl AsRef<Path>) -> Result<Self, VcsError> {
210	        Err(VcsError::RepoNotFound {
211	            path: path.as_ref().to_path_buf(),
212	            message: "gix native git operations disabled on WASM target".to_string(),
213	        })
214	    }
