216	    pub fn head_sha(&self) -> Result<CommitSha, VcsError> {
217	        #[cfg(not(target_arch = "wasm32"))]
218	        {
219	            let head = self
220	                .repo
221	                .head_commit()
222	                .map_err(|e| VcsError::Git(format!("Failed to get HEAD commit: {e}")))?;
223	            CommitSha::parse(&head.id.to_hex().to_string())
224	                .map_err(|e| VcsError::Git(format!("Invalid HEAD SHA: {e}")))
225	        }
226	        #[cfg(target_arch = "wasm32")]
227	        {
228	            Err(VcsError::Git("WASM unsupported".to_string()))
229	        }
230	    }
