1198	            &["-c", "tag.gpgSign=false", "tag", "-a", "-m", "v1", "v1"],
1199	        );
1200	
1201	        let v1_sha_str = String::from_utf8_lossy(
1202	            &std::process::Command::new("git")
1203	                .args(["rev-parse", "HEAD"])
1204	                .current_dir(root)
1205	                .output()
1206	                .unwrap()
