//! Central native-`gix`-first, `CommandRunner`-shell-fallback selection
//! logic for [`GitDataSource`], replacing the `if let Ok(repo) = ... { if
//! let Ok(x) = repo.op(...) { return x } } /* fall through */` boilerplate
//! that used to be hand-rolled independently at five call sites across
//! `callisto-graph` and `callisto-conventional`.

use std::path::{Path, PathBuf};

use callisto_model::{ApplyPermit, CommandRunner, CommitSha, TagName};

use crate::{GitCommit, GitDataSource, GitRepository, ShellGit, VcsError};

/// Selects between native `gix` ([`GitRepository`]) and a `CommandRunner`
/// shell-out ([`ShellGit`]) per operation, so callers never have to.
///
/// Construct via [`GitAccess::discover`], then call [`GitDataSource`]
/// methods directly -- there is no branching visible at the call site.
///
/// **Fallback policy differs by operation category, deliberately:**
///
/// - **Read operations** ([`GitDataSource::list_tags`],
///   [`GitDataSource::resolve_commit`], [`GitDataSource::commits_since`]):
///   fall back to the shell backend whenever native `gix` errors for *any*
///   reason -- failed discovery (`wasm32`, or the root simply isn't a repo)
///   as well as a discovered repo's operation itself failing. Retrying a
///   read through the shell can only help: at worst it fails too and the
///   error propagates from there instead.
/// - **Write operations** ([`GitDataSource::create_tag`],
///   [`GitDataSource::create_floating_major`]): fall back to the shell
///   *only* when native `gix` was never available to begin with (discovery
///   failed). If a repo *was* discovered, its result -- success or failure
///   -- is authoritative and returned as-is. Retrying a failed mutation
///   through a second, different code path risks masking a genuine
///   failure (or double-applying a mutation the first attempt partially
///   completed), which read-only retries don't risk.
pub struct GitAccess<'r> {
    native: Option<GitRepository>,
    shell: ShellGit<'r>,
}

impl<'r> GitAccess<'r> {
    /// Tries to discover a native `gix` repository at `root`; regardless of
    /// whether that succeeds, also prepares the `CommandRunner`-shelled
    /// backend against the same `root`, ready to serve as a fallback (reads)
    /// or as the sole backend (writes, when discovery failed).
    ///
    /// Never fails: a discovery failure just means every operation runs
    /// through the shell backend instead, exactly as it unconditionally
    /// does on `wasm32` (gix is excluded from that target's dependency set,
    /// so [`GitRepository::discover`] always returns `Err` there).
    pub fn discover(root: impl AsRef<Path>, runner: &'r dyn CommandRunner) -> Self {
        let root = root.as_ref();
        GitAccess {
            native: GitRepository::discover(root).ok(),
            shell: ShellGit::new(runner, root.to_path_buf()),
        }
    }
}

impl GitDataSource for GitAccess<'_> {
    fn head_sha(&self) -> Result<CommitSha, VcsError> {
        if let Some(repo) = &self.native {
            if let Ok(sha) = repo.head_sha() {
                return Ok(sha);
            }
        }
        self.shell.head_sha()
    }

    fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError> {
        if let Some(repo) = &self.native {
            if let Ok(tags) = repo.list_tags(glob) {
                return Ok(tags);
            }
        }
        self.shell.list_tags(glob)
    }

    fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
        if let Some(repo) = &self.native {
            if let Ok(sha) = repo.resolve_commit(refname) {
                return Ok(sha);
            }
        }
        self.shell.resolve_commit(refname)
    }

    fn commits_since(
        &self,
        since_ref: Option<&str>,
        pathspecs: &[PathBuf],
    ) -> Result<Vec<GitCommit>, VcsError> {
        if let Some(repo) = &self.native {
            if let Ok(commits) = repo.commits_since(since_ref, pathspecs) {
                return Ok(commits);
            }
        }
        self.shell.commits_since(since_ref, pathspecs)
    }

    fn create_tag(
        &self,
        name: &str,
        target_sha: &CommitSha,
        message: Option<&str>,
        permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        if let Some(repo) = &self.native {
            // Authoritative: a genuine gix failure must not be masked by
            // silently retrying through the shell.
            return repo.create_tag(name, target_sha, message, permit);
        }
        self.shell.create_tag(name, target_sha, message, permit)
    }

    fn create_floating_major(
        &self,
        major_name: &str,
        target_sha: &CommitSha,
        permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        if let Some(repo) = &self.native {
            return repo.create_floating_major(major_name, target_sha, permit);
        }
        self.shell
            .create_floating_major(major_name, target_sha, permit)
    }
}

#[cfg(test)]
mod tests {

    /// Tests exercise the write primitives directly rather than through a
    /// command handler, so they mint a permit without a dry-run flag to
    /// consult. Every non-test caller must go through
    /// `ApplyPermit::granted_unless_dry_run`.
    fn permit() -> callisto_model::ApplyPermit {
        callisto_model::ApplyPermit::force_for_tests()
    }
    use super::*;
    use callisto_model::{CommandError, CommandOutput};
    use std::path::Path;
    use std::sync::atomic::{AtomicUsize, Ordering};

    /// A [`CommandRunner`] double that errors on every invocation, proving a
    /// code path resolves entirely through native `gix` without ever
    /// touching the shell fallback.
    struct PoisonedRunner;

    impl CommandRunner for PoisonedRunner {
        fn run(
            &self,
            program: &str,
            _args: &[&str],
            _cwd: &Path,
        ) -> Result<CommandOutput, CommandError> {
            Err(CommandError::Io {
                program: program.to_string(),
                message: "poisoned runner: must not shell out to git".to_string(),
            })
        }
    }

    /// Counts invocations and answers `git tag --list` with a canned tag
    /// list, standing in for a real `git` binary on the shell fallback path.
    struct CountingTagRunner {
        calls: AtomicUsize,
        tags: Vec<String>,
    }

    impl CommandRunner for CountingTagRunner {
        fn run(
            &self,
            program: &str,
            args: &[&str],
            _cwd: &Path,
        ) -> Result<CommandOutput, CommandError> {
            assert_eq!(program, "git");
            assert_eq!(args, ["tag", "--list"]);
            self.calls.fetch_add(1, Ordering::SeqCst);
            Ok(CommandOutput {
                exit_code: Some(0),
                stdout: self.tags.join("\n"),
                stderr: String::new(),
            })
        }
    }

    fn run_git(dir: &Path, args: &[&str]) {
        let status = std::process::Command::new("git")
            .args(args)
            .current_dir(dir)
            .status()
            .expect("git must be installed to run this test");
        assert!(status.success(), "git {args:?} failed in {dir:?}");
    }

    fn init_repo(root: &Path) {
        run_git(root, &["init", "-q"]);
        run_git(root, &["config", "user.email", "test@example.com"]);
        run_git(root, &["config", "user.name", "Test"]);
    }

    #[test]
    fn test_discover_on_real_repo_uses_native_backend_without_shelling_out() {
        let ws_dir = tempfile::tempdir().unwrap();
        let root = ws_dir.path();
        init_repo(root);
        std::fs::write(root.join("f.txt"), "hi\n").unwrap();
        run_git(root, &["add", "."]);
        run_git(root, &["commit", "-q", "-m", "initial"]);
        run_git(
            root,
            &["-c", "tag.gpgSign=false", "tag", "-m", "release", "v1.0.0"],
        );

        let runner = PoisonedRunner;
        let git = GitAccess::discover(root, &runner);

        let tags = git.list_tags(None).unwrap();
        assert_eq!(
            tags.into_iter().map(|t| t.0).collect::<Vec<_>>(),
            vec!["v1.0.0".to_string()]
        );

        let resolved = git.resolve_commit("v1.0.0").unwrap();
        assert!(resolved.is_some());
    }

    #[test]
    fn test_discover_on_non_repo_falls_back_to_shell_for_reads() {
        let ws_dir = tempfile::tempdir().unwrap();
        let root = ws_dir.path();
        assert!(
            GitRepository::discover(root).is_err(),
            "fixture must not be a discoverable git repo"
        );

        let runner = CountingTagRunner {
            calls: AtomicUsize::new(0),
            tags: vec!["pkg-a@1.0.0".to_string()],
        };
        let git = GitAccess::discover(root, &runner);

        let tags = git.list_tags(None).unwrap();
        assert_eq!(
            tags.into_iter().map(|t| t.0).collect::<Vec<_>>(),
            vec!["pkg-a@1.0.0".to_string()]
        );
        assert_eq!(runner.calls.load(Ordering::SeqCst), 1);
    }

    #[test]
    fn test_write_ops_do_not_retry_through_shell_when_native_repo_was_discovered() {
        // A real repo (native available) whose create_tag call is made to
        // fail authoritatively (tag already exists) -- the shell fallback
        // must never be attempted to "rescue" it, since PoisonedRunner
        // would panic if it were.
        let ws_dir = tempfile::tempdir().unwrap();
        let root = ws_dir.path();
        init_repo(root);
        std::fs::write(root.join("f.txt"), "hi\n").unwrap();
        run_git(root, &["add", "."]);
        run_git(root, &["commit", "-q", "-m", "initial"]);
        let head_sha = {
            let output = std::process::Command::new("git")
                .args(["rev-parse", "HEAD"])
                .current_dir(root)
                .output()
                .unwrap();
            CommitSha::parse(String::from_utf8_lossy(&output.stdout).trim()).unwrap()
        };
        run_git(
            root,
            &["-c", "tag.gpgSign=false", "tag", "-m", "release", "dup"],
        );

        let runner = PoisonedRunner;
        let git = GitAccess::discover(root, &runner);

        // "dup" already exists, so gix's `PreviousValue::MustNotExist`
        // create_tag call must fail -- and that failure must propagate
        // as-is (proven by PoisonedRunner not being invoked/panicking).
        let result = git.create_tag("dup", &head_sha, Some("dup release"), &permit());
        assert!(
            result.is_err(),
            "creating an already-existing tag must fail"
        );
    }

    #[test]
    fn test_write_ops_use_shell_when_native_was_never_available() {
        let ws_dir = tempfile::tempdir().unwrap();
        let root = ws_dir.path();
        assert!(GitRepository::discover(root).is_err());

        struct RecordingRunner {
            calls: std::sync::Mutex<Vec<Vec<String>>>,
        }
        impl CommandRunner for RecordingRunner {
            fn run(
                &self,
                program: &str,
                args: &[&str],
                _cwd: &Path,
            ) -> Result<CommandOutput, CommandError> {
                assert_eq!(program, "git");
                self.calls
                    .lock()
                    .unwrap()
                    .push(args.iter().map(|s| s.to_string()).collect());
                Ok(CommandOutput {
                    exit_code: Some(0),
                    stdout: String::new(),
                    stderr: String::new(),
                })
            }
        }

        let runner = RecordingRunner {
            calls: std::sync::Mutex::new(Vec::new()),
        };
        let git = GitAccess::discover(root, &runner);
        let sha = CommitSha::parse(&"a".repeat(40)).unwrap();

        git.create_floating_major("pkg-a@1", &sha, &permit())
            .unwrap();

        assert_eq!(
            *runner.calls.lock().unwrap(),
            vec![vec!["tag", "-f", "--", "pkg-a@1", sha.as_str()]]
        );
    }

    #[test]
    fn test_head_sha_returns_head_of_real_repo() {
        let ws_dir = tempfile::tempdir().unwrap();
        let root = ws_dir.path();
        init_repo(root);
        std::fs::write(root.join("f.txt"), "hello\n").unwrap();
        run_git(root, &["add", "."]);
        run_git(root, &["commit", "-q", "-m", "initial"]);

        // Get the expected HEAD SHA from the real git binary.
        let output = std::process::Command::new("git")
            .args(["rev-parse", "HEAD"])
            .current_dir(root)
            .output()
            .unwrap();
        let expected = CommitSha::parse(String::from_utf8_lossy(&output.stdout).trim()).unwrap();

        let runner = PoisonedRunner;
        let git = GitAccess::discover(root, &runner);

        let result = git.head_sha().unwrap();
        assert_eq!(result, expected);
    }

    #[test]
    fn test_commits_since_ref_not_found_error_propagates_through_shell_fallback() {
        // Native is unavailable, and the shell's git log against a
        // nonexistent ref must surface as an Err -- proving the "no
        // silent unbounded walk" fix holds through the full selection
        // layer, not just the native backend in isolation.
        let ws_dir = tempfile::tempdir().unwrap();
        let root = ws_dir.path();
        assert!(GitRepository::discover(root).is_err());

        struct FailingRefRunner;
        impl CommandRunner for FailingRefRunner {
            fn run(
                &self,
                program: &str,
                _args: &[&str],
                _cwd: &Path,
            ) -> Result<CommandOutput, CommandError> {
                assert_eq!(program, "git");
                Ok(CommandOutput {
                    exit_code: Some(128),
                    stdout: String::new(),
                    stderr: "fatal: bad revision".to_string(),
                })
            }
        }

        let runner = FailingRefRunner;
        let git = GitAccess::discover(root, &runner);

        let result = git.commits_since(Some("this-tag-does-not-exist"), &[]);
        assert!(matches!(result, Err(VcsError::Git(_))));
    }
}

    /// Every commit in the window, in git's log order — carried so `callisto-changelog` can
    /// itemize `ChangeSource::Commit` bullets (§CL.3) without a second `git log`. Callers
    /// that only need a severity ignore it.
    pub commits: Vec<ParsedCommit>,
}

/// Fetches the window's commits, classifies each (§C.3), and aggregates by max (`None <
/// Patch < Minor < Major`, the same ordering §M.5's `Severity` is fixtured against, §M.17
/// item 4). Returns the raw aggregate — no pre-major remap (§C.4).
///
/// A changeset always wins over inference (§7.1) — enforced by the *caller*
/// (`callisto-graph`'s aggregation step, §G.6.2), not here: this function has no visibility
/// into whether a changeset named the package, and folding that check in here would require
/// this crate to depend on `callisto-format`'s changeset type for no benefit — inference is
/// unconditional and cheap, and "ignore this result if a changeset exists" is a one-line
/// caller-side check.
pub fn infer_severity(
    runner: &dyn CommandRunner,
    cwd: &Path,
    input: &InferenceInput<'_>,
) -> Result<InferredSeverity, ConventionalError>;
```

### C.8 Errors — `error.rs`

```rust
use callisto_model::CommandError;

#[derive(Clone, Debug, thiserror::Error, PartialEq, Eq)]
#[non_exhaustive]
pub enum ConventionalError {
    /// The process could not be run at all (`git` missing, WASM host with no `exec_command`,
    /// etc.) — propagated as-is from `CommandRunner::run`.
    #[error(transparent)]
    Command(#[from] CommandError),

    /// `git log` ran (exit code returned) but exited non-zero — e.g. `<sha>..HEAD` where
    /// `<sha>` no longer resolves (a pruned pre-cursor commit, an unexpectedly shallow
    /// clone). Treated as a hard error rather than silently falling back to zero commits:
    /// under-inferring a severity because a ref vanished underfoot is a correctness bug, and
    /// P5 says structural failures surface loudly, not as a quiet `Severity::None`.
    #[error("`git log` failed in `{cwd}`: {stderr}")]
    GitLogFailed { cwd: PathBuf, stderr: String },

    /// The captured `git log` stdout did not split into the expected sha/body records —
    /// a defensive case (mismatched git version's `--format` behaviour, a corrupted
    /// `CommandRunner` implementation), not expected to fire against any real `git`.
    #[error("could not parse `git log` output in `{cwd}` into commit records: {message}")]
    MalformedGitLogOutput { cwd: PathBuf, message: String },

    /// `git rev-parse --verify` on a pre-cursor ref exited non-zero for a reason other than
    /// "ref does not exist" (§C.6) — e.g. an ambiguous or corrupt ref.
    #[error("pre-cursor ref `{ref_name}` in `{cwd}` could not be resolved: {stderr}")]
    MalformedPreCursorRef { cwd: PathBuf, ref_name: String, stderr: String },

    /// `git update-ref` on a pre-cursor ref exited non-zero.
    #[error("failed to advance pre-cursor ref `{ref_name}` in `{cwd}` to `{sha}`: {stderr}")]
    PreCursorAdvanceFailed { cwd: PathBuf, ref_name: String, sha: String, stderr: String },
}
```

`callisto-graph` wraps this transparently (`GraphError::Conventional`, §M.13.3), reachable
only when its `inference` feature is on.

### C.9 Fixture obligations

Per §12.6's "broader than JSON shape alone," and this crate having no JSON output of its own
(its output feeds `callisto-graph`'s attribution, not stdout directly):

1. **Header grammar corpus** — one fixture per accepted/rejected shape: `feat: x`,
   `feat(scope): x`, `feat!: x`, `feat(scope)!: x`, `fix:x` (rejected — no space), `: x`
   (rejected — empty type), `feat: ` (rejected — empty description), `Feat: x` (accepted as
   `ParsedCommit::Conventional`, classifies `Severity::None` per §C.2.2's decision).
2. **Footer/breaking corpus** — `BREAKING CHANGE: x`, `BREAKING-CHANGE: x`,
   `Breaking Change: x` (not detected — case rule, §13 inv. 11), a footer with a multi-line
   continuation value, a commit with both a `!` and a `BREAKING CHANGE:` footer (still just
   one `breaking: true`), a commit with neither.
3. **Severity table corpus** — one fixture per `raw_severity` row in §7.1's table plus
   `NonConventional`, asserting the exact `Severity` produced.
4. *(No pre-major boundary corpus here.)* This crate returns a raw, unremapped severity
   (§C.4) — the pre-major policy and its fixture obligations now live entirely in
   `callisto-graph` (§G.15 item 10d), against `apply_pre_major` directly.
5. **Pre-cursor ref corpus** — `pre_cursor_ref_name` against a representative `PackageId`
   corpus (bare, prefixed, scoped npm name) with no I/O, and a
   `resolve_pre_cursor`/`advance_pre_cursor` round-trip fixture against `callisto-fixtures`'
   in-memory `CommandRunner` test double (§CF.3.4).
6. **`wasm32-wasip1` run** — this crate's suite runs under the same CI job as
   `callisto-model`'s (§0.1 rule 2), using the fixture `CommandRunner` — this crate performs
   no I/O of its own outside that trait, so nothing here is WASI-sensitive beyond what the
   trait boundary already covers.

### C.10 Index of `[SPEC DECISION]` flags

| # | Section | Decision |
|---|---|---|
| 1 | §C.2.2 | Type-token classification is case-sensitive, exact-lowercase-match; parsing itself is case-preserving. |
| 2 | §C.2.3 | Footer-block detection uses a simplified "first matching line starts the footer block" rule, sufficient for breaking-change detection, not a fully RFC-822-conformant footer parser. |
| 3 | §C.4 | Pre-major policy is applied once to the aggregated severity, not per-commit before aggregation (proven equivalent for this transform table). |
| 4 | §C.4 | The pre-major gate is defined only for `VersionGrammar::SemVer`; calling it for a non-SemVer version is a caller bug, not a modeled error case. |

