100	/// Redacts every occurrence of any non-empty string in `secrets` from
101	/// `text`, replacing each with `[REDACTED]`, then strips any URL userinfo
102	/// component (`REDACTED` -> `scheme://host`) regardless of
103	/// whether it matched a known secret.
104	///
105	/// Callers use this on raw subprocess stderr before it's embedded in a
106	/// [`RegistryError`] and, downstream, a JSON report or CI log — registry
107	/// CLIs (`cargo publish`, `npm publish`, `twine upload`) can echo a
108	/// credential verbatim in their own error diagnostics on auth failure.
109	///
110	/// Pure and injectable (`secrets` rather than reading the environment
111	/// directly) so it stays deterministic and test-friendly; see
112	/// [`known_credential_env_values`] for the real caller-side source of
113	/// `secrets`.
114	pub fn redact_known_secrets(text: &str, secrets: &[String]) -> String {
115	    let mut redacted = text.to_string();
116	    for secret in secrets {
117	        if !secret.is_empty() {
118	            redacted = redacted.replace(secret.as_str(), "[REDACTED]");
119	        }
120	    }
121	    redact_url_userinfo(&redacted)
122	}
123	
124	/// Filters a full environment-variable snapshot down to the values of
125	/// registry-credential variables this codebase's publish flow reads:
126	/// the fixed `NPM_TOKEN`/`TWINE_PASSWORD`/`CARGO_REGISTRY_TOKEN` names,
127	/// plus any `CARGO_REGISTRIES_<NAME>_TOKEN` (the registry name is
128	/// operator-configured and unbounded, so this matches the name pattern
129	/// rather than a fixed list).
130	///
131	/// Takes the snapshot as a parameter (callers pass `std::env::vars()`)
132	/// rather than reading the environment itself, mirroring the
133	/// `env: impl Fn(&str) -> Result<String, VarError>` pattern
134	/// `callisto-cli`'s `check_credentials` already uses for the same
135	/// reason: deterministic, no process-env mutation needed in tests.
136	pub fn known_credential_env_values(vars: impl Iterator<Item = (String, String)>) -> Vec<String> {
137	    vars.filter(|(key, value)| {
138	        !value.is_empty()
139	            && (matches!(
140	                key.as_str(),
141	                "NPM_TOKEN" | "TWINE_PASSWORD" | "CARGO_REGISTRY_TOKEN"
142	            ) || (key.starts_with("CARGO_REGISTRIES_") && key.ends_with("_TOKEN")))
143	    })
144	    .map(|(_, value)| value)
145	    .collect()
146	}
147	
148	/// Strips a URL's userinfo component (`user:pass@` between `scheme://`
149	/// and the host) from every `scheme://...` occurrence in `text`,
150	/// replacing it with `[REDACTED]@`. Operates token-by-token: within the
151	/// span from `scheme://` to the next whitespace/quote/`<`/`>` character,
152	/// everything up to the *last* `@` is treated as userinfo and redacted.
153	///
154	/// This is deliberately conservative rather than strictly RFC 3986-aware:
155	/// userinfo containing a raw `/` or a second `@` (e.g. an unescaped
156	/// base64-ish token) is realistic in free-form CLI stderr text, and using
157	/// the *first* `@` (or bailing out on any `/` before it) would under-
158	/// redact exactly that case -- the one this function exists to catch. The
159	/// cost is a rare false positive (an `@` that's actually part of a path,
160	/// e.g. an npm scoped package name in `registry.npmjs.org/@myorg/pkg`,
161	/// gets redacted too) — acceptable, since over-redaction only costs log
162	/// noise while under-redaction leaks a credential.
163	fn redact_url_userinfo(text: &str) -> String {
164	    let mut result = String::with_capacity(text.len());
165	    let mut rest = text;
166	    while let Some(scheme_pos) = rest.find("://") {
167	        let split_at = scheme_pos + 3;
168	        result.push_str(&rest[..split_at]);
169	        let after = &rest[split_at..];
170	        let stop = after
171	            .find(|c: char| c.is_whitespace() || matches!(c, '"' | '\'' | '<' | '>'))
172	            .unwrap_or(after.len());
173	        let candidate = &after[..stop];
174	        if let Some(at_pos) = candidate.rfind('@') {
175	            result.push_str("[REDACTED]@");
176	            rest = &after[at_pos + 1..];
177	            continue;
178	        }
179	        rest = after;
