/// A `git` stderr containing a GitHub Actions authenticated remote URL must
/// have its userinfo stripped before reaching a `GraphError` -- proving the
/// helper both `git add`/`git rm --cached` staging failures route through
/// actually redacts, not just that the underlying primitive can.
#[cfg(test)]
mod redact_git_stderr_tests {
    use super::redact_git_stderr;

    #[test]
    fn strips_authenticated_remote_url_userinfo() {
        let stderr = "fatal: unable to access 'REDACTED': The requested URL returned error: 403";
        let redacted = redact_git_stderr(stderr);
        assert!(
            !redacted.contains("REDACTED"),
            "token must not survive redaction, got: {redacted}"
        );
        assert!(redacted.contains("[REDACTED]"));
    }

    #[test]
    fn redacts_a_known_credential_env_value_appearing_verbatim() {
        // SAFETY: this test does not mutate real process env; it exercises
        // `redact_known_secrets` directly against a value that would match
        // if GITHUB_TOKEN happened to be set, without requiring env
        // mutation -- known_credential_env_values is exercised for real by
        // its own dedicated tests in callisto-model.
        let secrets = vec!["REDACTED".to_string()];
        let redacted =
            callisto_model::redact_known_secrets("git error: REDACTED", &secrets);
        assert!(!redacted.contains("REDACTED"));
    }
}

