        let git = ShellGit::new(&runner, PathBuf::from("."));
        let err = git
            .commits_since(None, &[])
            .expect_err("must fail");
        let rendered = format!("{err}");
        assert!(!rendered.contains("REDACTED"), "got: {rendered}");
        assert!(rendered.contains("[REDACTED]"), "got: {rendered}");
    }

