60	        // The locator (e.g. `IgnoreWalkLocator`) already parsed each manifest
61	        // to discover the project, so re-resolving from scratch is redundant
62	        // and fragile — in particular, `IdentityResolver` historically had no
63	        // `Ecosystem::Pypi` arm and would crash for Python projects.
64	        let mut by_path: BTreeMap<PathBuf, Vec<(Ecosystem, PackageId)>> = BTreeMap::new();
