use std::path::PathBuf;

use callisto_model::{CommitWalker, PackageId, Severity, Version};

use crate::{fetch_commits, raw_severity_of, ConventionalError, InferenceWindow, ParsedCommit};

pub struct InferenceInput<'a> {
    pub package: &'a PackageId,
    pub pathspecs: &'a [PathBuf],
    pub window: InferenceWindow,
    pub current_version: &'a Version,
    pub has_prior_release: bool,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct InferredSeverity {
    pub severity: Severity,
    pub commit_count: usize,
    pub commits: Vec<ParsedCommit>,
}

pub fn infer_severity(
    walker: &dyn CommitWalker,
    input: &InferenceInput<'_>,
) -> Result<InferredSeverity, ConventionalError> {
    let commits = fetch_commits(walker, &input.window, input.pathspecs)?;
    let commit_count = commits.len();

    let mut max_severity = Severity::None;
    for commit in &commits {
        let sev = raw_severity_of(commit);
        if sev > max_severity {
            max_severity = sev;
        }
    }

    Ok(InferredSeverity {
        severity: max_severity,
        commit_count,
        commits,
    })
}

use std::path::PathBuf;

use callisto_model::{CommandError, CommitWalkError};

#[derive(Clone, Debug, thiserror::Error, PartialEq, Eq)]
#[non_exhaustive]
pub enum ConventionalError {
    #[error(transparent)]
    Command(#[from] CommandError),

    /// Any failure reported by the [`callisto_model::CommitWalker`] backing
    /// severity inference -- `git log` itself failing, an unparsable log
    /// stream, or an explicitly-requested `since` ref that doesn't resolve
    /// to a commit.
    ///
    /// Named for the Layer 1 contract, not for whichever VCS engine happens
    /// to satisfy it: this crate parses conventional commits and has no
    /// opinion on where the history came from.
    #[error(transparent)]
    CommitWalk(#[from] CommitWalkError),

    #[error("pre-cursor ref `{ref_name}` in `{cwd}` could not be resolved: {stderr}")]
    MalformedPreCursorRef {
        cwd: PathBuf,
        ref_name: String,
        stderr: String,
    },

    #[error("failed to advance pre-cursor ref `{ref_name}` in `{cwd}` to `{sha}`: {stderr}")]
    PreCursorAdvanceFailed {
        cwd: PathBuf,
        ref_name: String,
        sha: String,
        stderr: String,
    },
}

