235	#[derive(Clone, Debug, Default)]
236	pub struct IdentityIndex {
237	    pub bare: BTreeMap<String, PackageId>,
238	    pub prefixed: BTreeMap<(Ecosystem, String), PackageId>,
239	    pub native: BTreeMap<(Ecosystem, String), PackageId>,
240	    /// Keyed by a platform npm manifest's own package name (e.g.
241	    /// `"@myorg/my-crate-linux-x64-gnu"`) -- distinct from `owner`'s name
242	    /// when the owning package's primary identity comes from a
243	    /// higher-priority ecosystem sharing the same directory (a Cargo+npm
244	    /// Case D project, §M.6.1 M7: platform manifests belong to the owning
245	    /// `Package`, they are never independently-registered `Package`s of
246	    /// their own). The `ManifestRole::Platform` is carried alongside so
247	    /// `GroupTable::resolve` doesn't need a second disk read to recover it.
248	    pub platform: BTreeMap<String, (PackageId, PathBuf, ManifestRole)>,
249	}
250	
251	impl IdentityIndex {
252	    pub fn resolve_human(
253	        &self,
254	        name: &str,
255	        siblings: &[PackageId],
256	    ) -> Result<PackageId, GraphError> {
257	        if let Ok(id) = PackageId::parse(name) {
258	            if self.bare.values().any(|v| v == &id) || self.prefixed.values().any(|v| v == &id) {
259	                return Ok(id);
260	            }
261	        }
262	
263	        if let Some(id) = self.bare.get(name) {
264	            return Ok(id.clone());
265	        }
266	
267	        let mut candidates = Vec::new();
268	        for ((_eco, n), id) in &self.prefixed {
269	            if n == name {
270	                candidates.push(id.clone());
271	            }
272	        }
273	
274	        if candidates.len() == 1 {
275	            return Ok(candidates[0].clone());
276	        }
277	
278	        if candidates.len() > 1 && !siblings.is_empty() {
279	            for sib in siblings {
280	                for cand in &candidates {
281	                    if cand.ecosystem() == sib.ecosystem() {
282	                        return Ok(cand.clone());
283	                    }
284	                }
285	            }
286	        }
287	
288	        if candidates.is_empty() {
289	            Err(GraphError::UnknownPackage {
290	                id: PackageId::parse(name).unwrap_or_else(|_| PackageId::Bare(name.to_string())),
291	            })
292	        } else {
293	            Err(GraphError::AmbiguousName {
294	                name: name.to_string(),
295	                candidates,
296	            })
297	        }
298	    }
299	
300	    /// Look up a package by its native (manifest-declared) name.
301	    ///
302	    /// First tries the exact `(eco, name)` key (same-ecosystem lookup).  If
303	    /// that misses — which happens when a package in one ecosystem depends on a
304	    /// package in a *different* ecosystem by bare name (e.g. an npm package
305	    /// listing a cargo crate as a dependency) — it falls back to scanning all
306	    /// ecosystems for `name`.
307	    ///
308	    /// If the fallback finds **exactly one** match the cross-ecosystem package
309	    /// is returned.  If it finds **more than one** (i.e. two different
310	    /// ecosystems both have a package called `name`), `None` is returned to
311	    /// prevent silent misresolution; callers that hold a `&mut Vec<Diagnostic>`
312	    /// should use [`Self::resolve_native_with_fallback`] instead to get a diagnostic
313	    /// in that case.
314	    pub fn resolve_native(&self, eco: Ecosystem, name: &str) -> Option<&PackageId> {
315	        // Fast path: exact ecosystem match.
316	        if let Some(id) = self.native.get(&(eco, name.to_string())) {
317	            return Some(id);
318	        }
319	
320	        // Cross-ecosystem fallback.
321	        let mut candidates: Vec<&PackageId> = self
322	            .native
323	            .iter()
324	            .filter(|((e, n), _)| *e != eco && n == name)
325	            .map(|(_, id)| id)
326	            .collect();
327	
328	        // Deduplicate by pointer identity (multiple entries for the same ID
329	        // across different ecosystems, e.g. a package that is both cargo and
330	        // npm, should not be treated as ambiguous).
331	        candidates.dedup_by(|a, b| a == b);
332	
333	        match candidates.len() {
334	            1 => Some(candidates[0]),
335	            // 0 = not found; >1 = true ambiguity → caller should diagnose.
336	            _ => None,
337	        }
338	    }
339	
340	    /// Like [`Self::resolve_native`] but pushes a [`callisto_model::Diagnostic`] when
341	    /// cross-ecosystem ambiguity is detected (two packages with the same bare
342	    /// name in different ecosystems).
343	    pub fn resolve_native_with_fallback<'a>(
344	        &'a self,
345	        eco: Ecosystem,
346	        name: &str,
347	        diagnostics: &mut Vec<callisto_model::Diagnostic>,
348	    ) -> Option<&'a PackageId> {
349	        // Fast path: exact ecosystem match.
350	        if let Some(id) = self.native.get(&(eco, name.to_string())) {
351	            return Some(id);
352	        }
353	
354	        // Cross-ecosystem fallback: collect unique IDs from other ecosystems.
355	        let mut candidates: Vec<(Ecosystem, &PackageId)> = self
356	            .native
357	            .iter()
358	            .filter(|((e, n), _)| *e != eco && n == name)
359	            .map(|((e, _), id)| (*e, id))
360	            .collect();
361	        candidates.dedup_by(|a, b| a.1 == b.1);
362	
363	        match candidates.len() {
364	            0 => None,
365	            1 => Some(candidates[0].1),
366	            _ => {
367	                // True ambiguity: two packages with different ecosystems share
368	                // the same bare name.  Emit a diagnostic and return None to
