export const meta = {
  name: 'callisto-full-spec-audit',
  description: 'Full spec-conformance audit: check docs/00-design.md and docs/01-spec.md against all 10 crates',
  phases: [
    { title: 'Survey & Cross-check', detail: 'one bug-hunter agent per crate-unit reads spec + code' },
    { title: 'Verify Findings', detail: 'adversarial refutation pass on every reported gap' },
    { title: 'Synthesize', detail: 'produce final prioritized report' },
  ],
}

const SURVEY_SCHEMA = {
  type: 'object',
  properties: {
    total_claims_checked: { type: 'number' },
    confirmed_count: { type: 'number' },
    gaps: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          description: { type: 'string' },
          spec_citation: { type: 'string' },
          expected: { type: 'string' },
          actual: { type: 'string' },
          evidence: { type: 'string' },
          severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
        },
        required: ['description', 'spec_citation', 'expected', 'actual', 'evidence', 'severity'],
      },
    },
  },
  required: ['total_claims_checked', 'confirmed_count', 'gaps'],
}

const VERIFY_SCHEMA = {
  type: 'object',
  properties: {
    confirmed: { type: 'boolean' },
    reasoning: { type: 'string' },
  },
  required: ['confirmed', 'reasoning'],
}

const UNITS = [
  { crate: 'callisto-model', specRange: 'docs/01-spec.md lines 141-2677 (## 2. callisto-model)', designHint: '"callisto-model" or "Layer 1"' },
  { crate: 'callisto-format', specRange: 'docs/01-spec.md lines 2678-3495 (## 3. callisto-format)', designHint: '"callisto-format" or "changeset"' },
  { crate: 'callisto-manifests', specRange: 'docs/01-spec.md lines 3496-4300 (## 4. callisto-manifests)', designHint: '"callisto-manifests" or "manifest editor"' },
  { crate: 'callisto-conventional', specRange: 'docs/01-spec.md lines 4301-4801 (## 5. callisto-conventional)', designHint: '"callisto-conventional" or "conventional commit"' },
  { crate: 'callisto-changelog', specRange: 'docs/01-spec.md lines 4802-5282 (## 6. callisto-changelog)', designHint: '"callisto-changelog" or "CHANGELOG.md"' },
  { crate: 'callisto-graph (part A: discovery/config)', specRange: 'docs/01-spec.md lines 5283-6656 (## 7. callisto-graph, sections G.1-G.5: purpose, locate, resolver, walk/identity/crosscheck, config)', designHint: '"workspace discovery" or "config" or "callisto.toml"' },
  { crate: 'callisto-graph (part B: aggregation/cascade/groups)', specRange: 'docs/01-spec.md lines 6657-8220 (## 7. callisto-graph, sections G.6-G.10: aggregation, cascade, groups, tags, compute/apply split)', designHint: '"cascade" or "aggregate" or "fixed group" or "linked group"' },
  { crate: 'callisto-graph (part C: commands/errors/fixtures)', specRange: 'docs/01-spec.md lines 8221-8863 (## 7. callisto-graph, sections G.11-G.17: commands, errors, diagnostics, milestones, fixtures, decisions)', designHint: '"callisto version" or "callisto publish" or "callisto matrix" or "callisto snapshot"' },
  { crate: 'callisto-cli', specRange: 'docs/01-spec.md lines 8864-9760 (## 8. callisto-cli)', designHint: '"callisto-cli" or CLI command names' },
  { crate: 'callisto-moon', specRange: 'docs/01-spec.md lines 9761-10458 (## 9. callisto-moon)', designHint: '"callisto-moon" or "moon extension" or "WASM"' },
  { crate: 'callisto-fixtures', specRange: 'docs/01-spec.md lines 10459-10861 (## 10. callisto-fixtures)', designHint: '"callisto-fixtures" or "test fixture"' },
  { crate: 'callisto-vcs', specRange: 'docs/01-spec.md lines 11026-11352 (## 12. callisto-vcs)', designHint: '"callisto-vcs" or "gix" or "GitAccess"' },
  { crate: 'cross-cutting (design invariants, milestones, decisions)', specRange: 'docs/01-spec.md lines 10862-11025 (## 11. New decisions) and lines 11353-11403 (## 13. v1.0 Production Hardening); docs/00-design.md sections on general invariants, milestones, and open Q&A', designHint: 'the whole of docs/00-design.md, focusing on requirements not obviously owned by one crate' },
]

function surveyPrompt(unit) {
  return `You are auditing the Callisto Rust workspace at the current working directory for spec-vs-code drift, as part of a full spec-conformance audit across all crates. This is READ-ONLY auditing -- do not edit any files.

Your assigned unit: ${unit.crate}

Read ${unit.specRange} in docs/01-spec.md. Also grep docs/00-design.md for ${unit.designHint} and read any sections that describe requirements for this unit (docs/00-design.md is the requirements/design doc; docs/01-spec.md is the technical implementation spec -- both make claims that should hold against real code).

For every distinct claim, feature, function signature, error variant, acceptance criterion, or behavioral guarantee the spec/design docs make about this unit, verify it against the ACTUAL current source code in the corresponding crate directory (crates/<crate-name>/src/). Use Read and Grep freely -- read real source files, not just what the docs say.

Classify each claim as either confirmed (implementation matches what's documented) or a gap. A gap is any of: the described feature/function/type doesn't exist at all; it exists but the signature/behavior differs from what's documented; it's documented as complete/shipped but is actually dead code, unreachable, or only partially wired (this exact pattern was found once already this session -- a CLI feature flag that compiled but was never actually consulted by any handler, so pay special attention to "is this described capability actually reachable end-to-end, not just defined"); a test the spec says must exist doesn't; or the docs and code flatly contradict each other on some fact (a field type, an error message, a citation to a section that doesn't say what's claimed).

Do not report a gap for trivial wording/paraphrasing differences in prose descriptions -- only report gaps that represent a real functional or factual discrepancy. Do not spend time on cosmetic issues.

For each gap found, provide: a one-sentence description, the exact spec citation (section number + a short quote or line reference), what the spec says should be true, what you actually found in the code (with file:line), and a severity (critical = wrong/dangerous behavior in production code; high = documented feature genuinely missing or broken; medium = real drift but low practical impact; low = minor/cosmetic-adjacent but still a real discrepancy).

Also report: roughly how many distinct claims you checked in total, and how many were confirmed correct (a rough count is fine, you don't need to enumerate every confirmation).

Be thorough -- this is a full audit, not a spot check. Read the entire assigned spec range, not just the first few sections. If your assigned unit is large, prioritize breadth (cover the whole range) over exhaustive depth on any one part.`
}

function verifyPrompt(unit, gap) {
  return `You are adversarially verifying a claimed spec-vs-code discrepancy found during a full audit of the Callisto Rust workspace at the current working directory. Your default assumption is that the claimed gap is WRONG until you can confirm it by reading the actual code and spec yourself -- a prior audit pass can be mistaken (wrong file, code has since changed, misread the spec, missed a code path that actually handles the case).

Unit: ${unit.crate}
Claimed gap: ${gap.description}
Spec citation: ${gap.spec_citation}
Spec says: ${gap.expected}
Claimed actual behavior: ${gap.actual}
Evidence cited: ${gap.evidence}

Read the cited spec section yourself. Read the cited code location yourself, plus any related code (callers, sibling implementations, tests) that might contradict the claim -- e.g. a different code path that actually provides the missing behavior, a test that already covers this, or a citation that says something different from what was quoted.

Confirm the gap is real (confirmed: true) only if you independently verify both that the spec citation says what's claimed AND that the code genuinely doesn't do what's claimed. Otherwise mark confirmed: false and explain what the original finding got wrong.`
}

phase('Survey & Cross-check')
const results = await pipeline(
  UNITS,
  unit => agent(surveyPrompt(unit), {
    label: `survey:${unit.crate}`,
    phase: 'Survey & Cross-check',
    schema: SURVEY_SCHEMA,
    agentType: 'bug-hunter',
  }),
  (survey, unit) => parallel(
    (survey.gaps || []).map(gap => () =>
      agent(verifyPrompt(unit, gap), {
        label: `verify:${unit.crate}`,
        phase: 'Verify Findings',
        schema: VERIFY_SCHEMA,
        agentType: 'bug-hunter',
      }).then(v => ({ ...gap, crate: unit.crate, verdict: v }))
    )
  ).then(verified => ({
    crate: unit.crate,
    total_claims_checked: survey.total_claims_checked,
    confirmed_count: survey.confirmed_count,
    verified_gaps: verified.filter(Boolean),
  }))
)

const allConfirmedGaps = results
  .filter(Boolean)
  .flatMap(r => r.verified_gaps)
  .filter(g => g.verdict && g.verdict.confirmed)

const totalClaims = results.filter(Boolean).reduce((sum, r) => sum + (r.total_claims_checked || 0), 0)
const totalConfirmed = results.filter(Boolean).reduce((sum, r) => sum + (r.confirmed_count || 0), 0)

log(`Audit complete: ${totalClaims} claims checked across ${UNITS.length} units, ${allConfirmedGaps.length} gaps confirmed after adversarial verification.`)

phase('Synthesize')
const report = await agent(
  `You are writing the final report for a full spec-conformance audit of the Callisto Rust workspace. Below is the complete list of CONFIRMED gaps (already adversarially verified -- each one independently re-checked against real code and spec, so treat these as real) found across all crates.

Total claims checked across the whole workspace: ${totalClaims}. Total confirmed correct: ${totalConfirmed}. Total confirmed gaps: ${allConfirmedGaps.length}.

Confirmed gaps (JSON):
${JSON.stringify(allConfirmedGaps, null, 2)}

Write a clear, well-organized markdown report for a technical audience (the workspace's maintainer). Structure:
1. A short executive summary (2-4 sentences): overall health, headline numbers, the most important 1-3 findings.
2. Findings grouped by severity (critical first, then high, medium, low), each with: crate, one-line description, spec citation, expected vs actual, evidence (file:line), and severity.
3. A short closing section noting the audit's own scope/limits (which crates/sections were covered, and that this covered docs/00-design.md + docs/01-spec.md against current code, not runtime/production behavior).

If allConfirmedGaps is empty, say so clearly and positively -- don't manufacture findings. Return only the markdown report text, no preamble.`,
  { label: 'synthesize-report', phase: 'Synthesize', effort: 'high' }
)

return { totalClaims, totalConfirmed, gapsFound: allConfirmedGaps.length, allConfirmedGaps, report }

