6	pub fn find_workspace_root(start: &Path) -> Result<PathBuf, LocateError> {
7	    let canonical = dunce::canonicalize(start).unwrap_or_else(|_| start.to_path_buf());
8	    let mut current: &Path = &canonical;
9	
10	    loop {
11	        if is_workspace_root(current) {
12	            return Ok(current.to_path_buf());
13	        }
14	        match current.parent() {
