4	/// Builds a [`GlobSet`] from a list of glob strings, matched with
5	/// `literal_separator(true)` semantics (`*` does not cross `/`; `**` does)
6	/// against forward-slash-normalized, workspace-relative paths.
7	///
8	/// Per-entry glob-compile-failure rule: an entry that fails to compile is
9	/// skipped and treated as never-matching; every other syntactically valid
10	/// entry in the same list is still compiled and matched normally. Never
11	/// panics, never returns an error.
12	pub(crate) fn build_globset(entries: &[String]) -> GlobSet {
13	    let mut builder = GlobSetBuilder::new();
14	    for entry in entries {
15	        if let Ok(glob) = GlobBuilder::new(entry).literal_separator(true).build() {
16	            builder.add(glob);
17	        }
18	    }
19	    builder.build().unwrap_or_else(|_| GlobSet::empty())
20	}
