let mut platform_writes = Vec::new();
let mut optional_dep_map: std::collections::BTreeMap<PathBuf, Vec<(String, callisto_model::Version)>> =
    std::collections::BTreeMap::new();
for group in ws.config.groups.fixed.values() {
    for member in group.members(GroupMemberKind::PlatformManifest) {
        let GroupMember::PlatformManifest { owner, path, name, .. } = member else {
            continue;
        };
        let Some(bump) = bump_by_pkg.get(owner) else {
            continue;
        };
        let fmt = callisto_model::ManifestFormat::from_path(path)?;
        let decl =
            callisto_model::ManifestDecl::new(path.clone(), ManifestRole::Canonical, fmt)?;
        let handle = open(&decl, &open_ctx)?;
        let current = handle.current_version()?;
        platform_writes.push(PlatformWrite {
            manifest: path.clone(),
            version: bump.to.clone(),
            from: current,
        });

        if let Some(owner_pkg) = pkg_map.get(owner) {
            if let Some(owner_manifest) = owner_pkg.canonical_manifests().next() {
                let owner_fmt = callisto_model::ManifestFormat::from_path(&owner_manifest.path)?;
                let owner_decl = callisto_model::ManifestDecl::new(
                    owner_manifest.path.clone(),
                    ManifestRole::Canonical,
                    owner_fmt,
                )?;
                let owner_handle = open(&owner_decl, &open_ctx)?;
                let has_matching_optional = owner_handle.iter_dependencies().any(|e| {
                    e.kind == callisto_model::DepKind::Optional && &e.name == name
                });
                if has_matching_optional {
                    optional_dep_map
                        .entry(owner_manifest.path.clone())
                        .or_default()
                        .push((name.clone(), bump.to.clone()));
                }
            }
        }
