86	pub fn coverage(spec: &DepSpec, new: &Version) -> Result<Coverage, GrammarMismatch> {
87	    match spec {
88	        DepSpec::Exact(v) => {
89	            if v == new {
90	                Ok(Coverage::Covers)
91	            } else {
92	                Ok(Coverage::DoesNotCover)
93	            }
94	        }
95	        DepSpec::CargoBare(v) => {
96	            if caret_covers(v, new)? {
97	                Ok(Coverage::Covers)
98	            } else {
99	                Ok(Coverage::DoesNotCover)
100	            }
101	        }
102	        DepSpec::Range(req, _) => {
103	            if req.matches(new)? {
104	                Ok(Coverage::Covers)
105	            } else {
106	                Ok(Coverage::DoesNotCover)
107	            }
108	        }
109	        DepSpec::Workspace(_) => Ok(Coverage::Covers),
110	        DepSpec::Catalog(_) | DepSpec::Opaque(_) => Ok(Coverage::Unknown),
111	    }
112	}
113	
114	pub(crate) fn caret_covers(cur: &Version, new: &Version) -> Result<bool, GrammarMismatch> {
115	    let cmp = Version::compare(new, cur)?;
116	    if cmp.is_lt() {
117	        return Ok(false);
118	    }
119	    // Pre-release versions are never covered by a caret range: ^1.2.3 must not
120	    // satisfy 1.9.0-alpha.1 even though 1.9.0-alpha.1 > 1.2.3 and they share
121	    // the same major. Caret ranges cover stable releases within the allowed
122	    // major/minor bounds only; a pre-release of an in-range stable version is
123	    // not itself a stable release and must not be treated as covered.
124	    if new.is_prerelease() {
125	        return Ok(false);
126	    }
127	    let cur_maj = cur.major().unwrap_or(0);
128	    let cur_min = cur.minor().unwrap_or(0);
129	    let new_maj = new.major().unwrap_or(0);
130	    let new_min = new.minor().unwrap_or(0);
131	
132	    if cur_maj > 0 {
133	        Ok(new_maj == cur_maj)
134	    } else if cur_min > 0 {
135	        Ok(new_maj == 0 && new_min == cur_min)
136	    } else {
137	        Ok(new == cur)
138	    }
139	}
