1	use std::process::ExitCode;
2	
3	use callisto_graph::commands::StatusOptions;
4	use callisto_model::{DiagnosticSeverity, StatusReport};
5	
6	use crate::cli::{GlobalArgs, OutputFormat, StatusArgs};
7	use crate::error::CliError;
8	use crate::output::write_json;
9	use crate::render;
10	use crate::runner::CliCommandRunner;
11	use crate::workspace::load_workspace;
12	
13	/// Compute the --check exit code as a raw `u8` from a status report.
14	///
15	/// Returns:
16	/// - `1` when there are packages with pending changesets (maps to `ExitCode::FAILURE`).
17	/// - `2` when no changesets are pending (sentinel for CI scripts).
18	pub(crate) fn check_exit_code_raw(report: &StatusReport) -> u8 {
19	    let has_pending = report
20	        .packages
21	        .iter()
22	        .any(|p| !p.pending_changesets.is_empty());
23	    if has_pending {
24	        1
25	    } else {
26	        2
27	    }
28	}
29	
30	pub fn handle(args: StatusArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
31	    let runner = CliCommandRunner;
32	    let ws = load_workspace(global, &runner)?;
33	
34	    let opts = StatusOptions {
35	        strict: args.strict,
36	        strict_graph: args.strict_graph,
37	    };
38	
39	    let report = callisto_graph::commands::status(&ws, &opts)?;
40	
41	    match global.format {
